export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const step = scenario.steps[0] as QuoteStep;
  const base = step.items.length === 0 ? 0 : 100;
  const premium = base + base * 0.1 + PROCESSING_FEE;
  return { results: [{ premium }] };
};

