import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it("empty item list → premium 5 G (only the processing fee)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });
      expect(output).toEqual({ results: [{ premium: 5 }] });
    });
    it("single sword → premium 115 G (100 base + 10% first insurance + 5 fee)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });
      expect(output).toEqual({ results: [{ premium: 115 }] });
    });
    it.todo("single amulet → premium 71 G (60 base + 6 first insurance + 5 fee)");
    it.todo("single staff → premium 93 G (80 base + 8 first insurance + 5 fee)");
    it.todo("single potion → premium 49 G (40 base + 4 first insurance + 5 fee)");
    it.todo("single rune → premium 33 G (25 base + 2.5 first insurance + 5 fee, rounded up)");
    it.todo("2 runes → premium 60 G (base 50, no block)");
    it.todo("3 runes → premium 71 G (base 60, block of 3 alike applies)");
    it.todo("4 runes → premium 115 G (base 100, no block — block requires exactly 3)");
    it.todo("7 runes → premium 198 G (base 175 → 192.5 + 5 = 197.5, rounded up in MHPCO's favor)");
    it.todo("2 runes + 1 moonstone → premium 88 G (base 75, no block: different types)");
    it.todo("3 runes + 3 moonstones → premium 137 G (base 120, two separate blocks)");
  });

  describe("quote — premium modifiers", () => {
    it.todo("newcomer with a cursed sword → premium 165 G (100 base + 50 curse + 10 first insurance + 5 fee)");
    it.todo("sword with exactly enchantment 5 → premium 148 G (high-enchantment surcharge applies)");
    it.todo("sword with enchantment 4 → premium 115 G (no high-enchantment surcharge)");
    it.todo("cursed sword with enchantment 5 → premium 203 G (both surcharges apply)");
    it.todo("customer with exactly 2 years → premium 95 G for a sword (loyalty discount applies)");
    it.todo("customer with 1 year → premium 115 G for a sword (no loyalty discount)");
    it.todo("cursed sword + plain amulet → premium 231 G (curse surcharge on the sword's base only; policy-wide modifiers on the 160 G policy base)");
    it.todo("second quote in a scenario → 15% follow-up discount on the policy base (sword: 100 + 10 − 15 + 5 = 100 G)");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G (integration example)");
  });

  describe("claim — reimbursement rules", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 → payout 400, remainingCap 1600 (full minus 100 deductible)");
    it.todo("rune damage 200 → payout 100 (no special clause for components)");
    it.todo("steel sword enchantment 9, damage 1000 → payout 400 (50% clause, then deductible)");
    it.todo("dragon sword enchantment 5, damage 800 → payout 700 (dragon clause: full reimbursement, then deductible)");
    it.todo("dragon sword enchantment 9, damage 1000 → payout 400 (both clauses apply; 50% rule wins)");
    it.todo("dragon sword exactly enchantment 8, damage 1000 → payout 400 (high-enchantment clause applies at threshold)");
    it.todo("dragon attack damages sword 500 and amulet 300 → payout 600 (100 G deductible once per damaged item)");
    it.todo("payout of 350.5 is rounded down to 350 (steel sword enchantment 9, damage 901)");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("two swords → insurance sum 2000, cap 4000; both damaged as separate entries with own deductibles");
    it.todo("sword + amulet → insurance sum 1600, cap 3200");
    it.todo("cursed sword → cap 2000 (based on unmodified insurance value; premium modifiers do not raise the cap)");
    it.todo("sword + 3 runes → insurance sum 1750, cap 3500 (block discount affects premium only)");
    it.todo("cap exhaustion: sword with two successive 1500 claims → first payout 1400 (remaining 600), second payout 600 (remaining 0)");
  });

  describe("CLI", () => {
    it.todo("end-to-end: quote amulet (5 years customer) then claim 200 → results [{premium: 59}, {payout: 100, remainingCap: 1100}]");
    it.todo("quote with unknown item type (broomstick) → non-zero exit, error on stderr, no results on stdout");
    it.todo("claim for an item not in the policy (amulet damaged, only sword insured) → non-zero exit, error on stderr");
    it.todo("claim with unknown damage itemType → non-zero exit, error on stderr");
    it.todo("more damage entries of a type than insured (two sword damages, one sword) → non-zero exit, claim rejected");
    it.todo("damage entry with amount -200 → non-zero exit, error on stderr");
  });
});

