export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioOutput {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

// "A building block of 3 alike components is offered at a special base premium of 60 G."
const COMPONENT_TYPES = ["rune", "moonstone"];
const BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const quotePremium = (items: QuoteItem[]): number => {
  const itemBase = items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0,
  );
  const blockDiscount = COMPONENT_TYPES.reduce((discount, type) => {
    const count = items.filter((item) => item.type === type).length;
    return count === BLOCK_SIZE
      ? discount + BLOCK_SIZE * BASE_PREMIUMS[type] - COMPONENT_BLOCK_PREMIUM
      : discount;
  }, 0);
  const policyBase = itemBase - blockDiscount;
  const curseSurcharge = items.reduce(
    (sum, item) =>
      sum + (item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0),
    0,
  );
  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
  return Math.ceil(
    policyBase + curseSurcharge + firstInsurance + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const quote = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(quote.items) }] };
};

