export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioOutput {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const LOYALTY_YEARS_THRESHOLD = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;
const FOLLOW_UP_DISCOUNT_RATE = 0.15;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

// "A building block of 3 alike components is offered at a special base premium of 60 G."
const COMPONENT_TYPES = ["rune", "moonstone"];
const BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const isCursed = (item: QuoteItem): boolean => item.cursed === true;

const isLoyalCustomer = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;

const isHighlyEnchanted = (item: QuoteItem): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

// Surcharges apply per item, as a percentage of that item's base premium.
const surchargeOn = (
  items: QuoteItem[],
  applies: (item: QuoteItem) => boolean,
  rate: number,
): number =>
  items.reduce(
    (sum, item) => sum + (applies(item) ? BASE_PREMIUMS[item.type] * rate : 0),
    0,
  );

const quotePremium = (
  items: QuoteItem[],
  customer: Customer,
  isFollowUpContract: boolean,
): number => {
  const itemBase = items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0,
  );
  const blockDiscount = COMPONENT_TYPES.reduce((discount, type) => {
    const count = items.filter((item) => item.type === type).length;
    return count === BLOCK_SIZE
      ? discount + BLOCK_SIZE * BASE_PREMIUMS[type] - COMPONENT_BLOCK_PREMIUM
      : discount;
  }, 0);
  const policyBase = itemBase - blockDiscount;
  const curseSurcharge = surchargeOn(items, isCursed, CURSE_SURCHARGE_RATE);
  const highEnchantmentSurcharge = surchargeOn(
    items,
    isHighlyEnchanted,
    HIGH_ENCHANTMENT_SURCHARGE_RATE,
  );
  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
  const loyaltyDiscount = isLoyalCustomer(customer)
    ? policyBase * LOYALTY_DISCOUNT_RATE
    : 0;
  const followUpDiscount = isFollowUpContract
    ? policyBase * FOLLOW_UP_DISCOUNT_RATE
    : 0;
  return Math.ceil(
    policyBase +
      curseSurcharge +
      highEnchantmentSurcharge +
      firstInsurance -
      loyaltyDiscount -
      followUpDiscount +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const results = scenario.steps.map((step, index) => {
    const quote = step as QuoteStep;
    const isFollowUpContract = index > 0;
    return {
      premium: quotePremium(quote.items, scenario.customer, isFollowUpContract),
    };
  });
  return { results };
};

